source_units.raw_tex:
We assume throughout that
\begin{empheq}[box=\mybluebox]{equation}
\text{$X := \RR^J$,}
\end{empheq}
which we equip with 
the standard inner product $\scal{\cdot}{\cdot}$ and 
the induced Euclidean norm $\|\cdot\|$.

Now assume that 
\begin{empheq}[box=\mybluebox]{equation}
\text{$f \colon X \to\left]-\infty, +\infty\right]$ is convex and
differentiable on $U := \intdom f \neq\varnothing$.}
\end{empheq}

The \emph{Bregman distance}\footnote{Note that $D_f$ is
\emph{not} a distance in the sense of metric topology; however,
this naming convention is now ubiquitous.}  associated with $f$, 
first explored by Bregman in \cite{Bre67} (see also
\cite{CZ97}), is 
\begin{equation} 
\label{e:Df}
D_f \colon X \times X \to \left[0, +\infty\right] \colon (x,y) \mapsto
\begin{cases}
f(x) -f(y) -\scal{\nabla f(y)}{x -y}, &\text{~if~} y\in U; \\
+\infty, &\text{~otherwise}.
\end{cases}
\end{equation}

\begin{equation}
\label{e:bba}
\benv[\gamma]{\theta} \colon X\to \left[-\infty, +\infty\right] \colon
y\mapsto \inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\end{equation}
and

\begin{equation}
\label{e:fba}
\fenv[\gamma]{\theta} \colon X \to \left[-\infty, +\infty\right] \colon
x \mapsto
\inf_{y\in X} \big(\theta(y) +\frac{1}{\gamma}D_f(x,y)\big),
\end{equation}
respectively.

\begin{proposition}
\label{p:12.22i}
Let $\theta \colon X \to \left]-\infty, +\infty\right]$, 
let $\gamma \in \RPP$, and let $\mu \in \RPP$.
Then $\benv[\mu]{\gamma\theta} =\gamma\benv[\gamma\mu]{\theta}$ 
and $\fenv[\mu]{\gamma\theta} =\gamma\fenv[\gamma\mu]{\theta}$.
\end{proposition}

\begin{proof}
This is analogous to the proof of \cite[Proposition~12.22(i)]{BC17}.
\end{proof}

From now on, we strengthen our assumptions by requiring that 
\begin{empheq}[box=\mybluebox]{equation}
\label{e:fLegendre}
\text{$f\in\Gamma_0(X)$ is a convex function of Legendre type and
$U := \intdom f$.}
\end{empheq}
This will allow us to obtain a quite satisfying theory in which
the envelopes are convex functions. 
Note that $f$ is essentially smooth and essentially strictly convex in the sense of \cite[Section~26]{Roc70}.

It is well known that
\begin{equation}
\label{e:Leggy}
\nabla f\colon U\to U^*:= \intdom f^*
\text{~is a homeomorphism with~}
\big(\nabla f\big)^{-1} = \nabla f^*.
\end{equation}

We will also work with the following standard assumptions:
\begin{itemize}
\item[\bfseries A1] 
$\nabla^2 f$ exists and is continuous on $U$;

\item[\bfseries A4] 
$(\forall x\in U)$ $D_f(x,\cdot)$ is coercive, i.e., 
$D_f(x, y) \to +\infty$ as $\|y\| \to +\infty$.
\end{itemize}
We also henceforth assume that 
\begin{empheq}[box=\mybluebox]{equation}
\text{all assumptions \textbf{A1}--\textbf{A4} hold.}
\end{empheq}

\begin{fact} 
\label{f:coeR}
Let $\theta\in\Gamma_0(X)$ be such that $\dom\theta\cap U\neq\varnothing$ and let $\gamma \in \RPP$.
Consider the following properties:
\begin{itemize}
\item[\rm (a)]
$U\cap \dom\theta$ is bounded.
\item[\rm (b)]
$\inf\theta(U)>-\infty$.
\item[\rm (c)]
$f$ is supercoercive, i.e., 
$f(x)/\|x\| \to +\infty$ as $\|x\| \to +\infty$.
\item[\rm (d)]
$(\forall x\in U)$ $D_f(x,\cdot)$ is supercoercive.
\end{itemize}
Then the following hold:
\begin{enumerate}
\item \label{l:coeRi}
If any of the conditions (a), (b), or (c) holds, then 
\begin{equation} \label{e:bcoeR}
(\forall y \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(\cdot,y) \;\;
\text{is coercive}
\end{equation}
or, equivalently,
\begin{equation}
\frac{1}{\gamma}\ran\nabla f \subseteq \intdom\left(\frac{1}{\gamma}f +\theta\right)^*.
\label{e:brilliantissimo}
\end{equation}

\item \label{l:coeRii}
If any of the conditions (a), (b), or (d) holds, then 
\begin{equation} \label{e:fcoeR}
(\forall x \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(x,\cdot) \;\;
\text{is coercive.}
\end{equation}
\end{enumerate}
\end{fact}

\begin{equation} \label{e:bcoeR}
(\forall y \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(\cdot,y) \;\;
\text{is coercive}
\end{equation}

\begin{equation} \label{e:fcoeR}
(\forall x \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(x,\cdot) \;\;
\text{is coercive.}
\end{equation}

\begin{proof}
Since $\frac{1}{\gamma}D_f =D_{\frac{1}{\gamma}f}$,
the result follows from \cite[Lemma~2.12]{BCN06} 
applied to $\tfrac{1}{\gamma}f$.
\end{proof}

\begin{proposition} 
\label{p:exact} 
Let $\theta \colon X \to \left]-\infty, +\infty\right]$ be convex
and such that $U\cap \dom\theta\neq\varnothing$, and let $\gamma \in \RPP$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:exact_left}
$\benv[\gamma]{\theta}$ is convex and continuous on $U$, and
	\begin{enumerate}
	\item 
	if \eqref{e:bcoeR} holds, i.e., $(\forall y \in U)$ $\theta(\cdot) +\frac{1}{\gamma}D_f(\cdot,y)$ is coercive, 
	then $\benv[\gamma]{\theta}$ is proper; 
	\item
	if $\theta\in\Gamma_0(X)$ and $\theta(\cdot) +\frac{1}{\gamma}D_f(\cdot,y)$ is coercive for a given $y\in U$, 
	then there exists a unique point $z\in U$ such that $\benv[\gamma]{\theta}(y)=\theta(z) +\frac{1}{\gamma}D_f(z,y)$.
	\end{enumerate}

\item 
\label{p:exact_right} 
$\fenv[\gamma]{\theta}$ is convex and continuous on $U$, and
	\begin{enumerate}
	\item 
	if \eqref{e:fcoeR} holds, i.e., $(\forall x \in U)$ $\theta(\cdot) +\frac{1}{\gamma}D_f(x,\cdot)$ is coercive, 
	then $\fenv[\gamma]{\theta}$ is proper; 
	\item
	if $\theta\in\Gamma_0(X)$ and $\theta(\cdot) +\frac{1}{\gamma}D_f(x,\cdot)$ is coercive for a given $x\in U$, 
	then there exists a unique point $z\in U$ such that $\fenv[\gamma]{\theta}(z)=\theta(z) +\frac{1}{\gamma}D_f(x,z)$.
	\end{enumerate}
\end{enumerate}
\end{proposition}

\begin{proof}
Since $\frac{1}{\gamma}D_f =D_{\frac{1}{\gamma}f}$,
the result follows from
 \cite[Propositions~3.4 and 3.5]{BCN06}
applied to $\tfrac{1}{\gamma}f$.
\end{proof}

If \eqref{e:fcoeR} holds for $\gamma =1$, then 
the \emph{right proximity operator} associated with $\theta$ is
\begin{equation} \label{e:dfprox}
\fprox{\theta}\colon U \to  U \colon
x \mapsto
\underset{y\in X}{\operatorname{argmin}}\;\: \big(\theta(y) +D_f(x,y)\big).
\end{equation}
\end{definition}

We thus derive from the definition that if \eqref{e:bcoeR} holds, then
\begin{subequations}
\label{e:benv-bproxall}
\begin{equation}
\label{e:benv-bprox}
\benv[\gamma]{\theta}(y) =\theta\big(\bprox{\gamma\theta}(y)\big) 
+\frac{1}{\gamma}D_f\big(\bprox{\gamma\theta}(y), y\big)
\end{equation}

and, by combining with \cref{p:12.9}\ref{p:12.9_left},
\begin{equation}
\label{e:benv-bprox'}
\theta\big(\bprox{\gamma\theta}(y)\big) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
\end{subequations}

Similarly, if \eqref{e:fcoeR} holds, then
\begin{subequations}
\label{e:fenv-fproxall}
\begin{equation}
\label{e:fenv-fprox}
\fenv[\gamma]{\theta}(x) =\theta\big(\fprox{\gamma\theta}(x)\big) +
\frac{1}{\gamma}D_f\big(x, \fprox{\gamma\theta}(x)\big)
\end{equation}

and 
\begin{equation}
\theta\big(\fprox{\gamma\theta}(x)\big) \leq \fenv[\gamma]{\theta}(x) \leq \theta(x).
\end{equation}
\end{subequations}
\end{remark}

\begin{proposition}
\label{p:prox}
Let $\theta\in\Gamma_0(X)$ be such that $\dom\theta\cap U\neq\varnothing$ and let $\gamma \in \RPP$.
\begin{enumerate}
\item 
\label{p:prox_left}
Suppose that \eqref{e:bcoeR} holds.
Then for every $(x,y) \in U\times U$, 
the following conditions are equivalent:
	\begin{enumerate}
	\item 
	$x =\bprox{\gamma\theta}(y)$,
	\item 
	$0 \in \gamma\partial\theta(x) +\nabla f(x) -\nabla f(y)$,
	\item 
	$(\forall z \in X)\quad \scal{\nabla f(y) -\nabla f(x)}{z -x} +\gamma\theta(x) \leq \gamma\theta(z)$.
	\end{enumerate}
Moreover, 
\begin{equation} \label{e:pro}
\bprox{\gamma\theta}=(\nabla f +\gamma\partial\theta)^{-1}\circ \nabla f 
\end{equation}
is continuous on $U$. 
\item 
\label{p:prox_right}
Suppose that \eqref{e:fcoeR} holds. 
Then for every $(x,y) \in U\times U$, 
the following conditions are equivalent:
	\begin{enumerate}
	\item 
	$y =\fprox{\gamma\theta}(x)$,
	\item 
	$0 \in \gamma\partial\theta(y) +\nabla^2 f(y)(y -x)$,
	\item 
	$(\forall z \in X)\quad \scal{\nabla^2 f(y)(x -y)}{z -y} +\gamma\theta(y) \leq \gamma\theta(z)$.
	\end{enumerate}
Moreover, $\fprox{\gamma\theta}$ is continuous on $U$. 
\end{enumerate}
\end{proposition}

\begin{proof}
Apply \cite[Proposition~3.10]{BCN06} to $\gamma\theta$.
\end{proof}

\begin{lemma}
\label{l:cvg}
Let $C$ be a compact subset of a Hausdorff space $\mathcal X$,
let $\phi\colon \mathcal X \to \left[-\infty, +\infty\right]$ be lower 
semicontinuous,
let $(x_a)_{a\in A}$ be a net in $C$,
and suppose that $\phi(x_a) \to \inf\phi(\mathcal X)$. 
Then $\argmin\phi \neq\varnothing$ 
and all cluster points of $(x_a)_{a\in A}$ lie in $\argmin\phi$.
Consequently, if $\phi$ attains its minimum at a unique point $u$, then $x_a \to u$.
\end{lemma}

\begin{proof}
This follows from the lower semicontinuity of $\phi$ and \cite[Lemma 1.14]{BC17}.
\end{proof}

\begin{proposition} 
\label{p:12.9} 
Let $\theta \colon X \to \left]-\infty, +\infty\right]$ be such that $U\cap \dom\theta\neq\varnothing$ and let $\gamma \in \RPP$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:12.9_left}
$\dom\benv[\gamma]{\theta}=U$, 
and $(\forall y\in U)(\forall\mu \in \left]\gamma, +\infty\right[)$ 
$\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y)$.
Consequently, $\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$, 
and $\benv[\gamma]{\theta}(y) \downarrow \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\item 
\label{p:12.9_right}
$\dom\fenv[\gamma]{\theta}=\dom f$, 
and $(\forall x \in U)(\forall\mu \in \left]\gamma, +\infty\right[)$ 
$\inf \theta(X) \leq \fenv[\mu]{\theta}(x) \leq \fenv[\gamma]{\theta}(x) \leq \theta(x)$.
Consequently, $\inf \theta(X) \leq \inf \fenv[\gamma]{\theta}(X) \leq \inf \theta(U)$, 
and $\fenv[\gamma]{\theta}(x) \downarrow \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:12.9_left}: We first show that $\dom\benv[\gamma]{\theta}=U$.
Let $y \in \dom\benv[\gamma]{\theta}$. 
Then $\benv[\gamma]{\theta}(y) =\inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big) <+\infty$,
and hence there exists $x \in X$ such that $\theta(x) +\frac{1}{\gamma}D_f(x,y) <+\infty$.
Since $\theta(x) >-\infty$, this yields $y \in U$.

From now on, let $y \in U$, and pick $u \in \dom\theta \cap U$. 
Then $-f(y) <+\infty$, $\|\nabla f(y)\| <+\infty$, $f(u) <+\infty$, $\theta(u) <+\infty$, and
\begin{subequations}
\begin{align}
\benv[\gamma]{\theta}(y) &=\inf_{x\in X} \Big(\theta(x) +\frac{1}{\gamma}\big(f(x) -f(y) -\scal{\nabla f(y)}{x -y}\big)\Big), \\ 
&\leq \theta(u) +\frac{1}{\gamma}\big(f(u) -f(y) -\scal{\nabla f(y)}{u -y}\big) <+\infty,
\end{align}
\end{subequations} 
which gives $y \in \dom\benv[\gamma]{\theta}$. Hence, $\dom \benv[\gamma]{\theta} =U$. 

Next, let $\mu \in \left]\gamma, +\infty\right[$. 
Then $\frac{1}{\mu} < \frac{1}{\gamma}$, 
$\theta \leq \theta +\frac{1}{\mu}D_f(\cdot,y) \leq \theta +\frac{1}{\gamma}D_f(\cdot,y)$, and so
\begin{equation}
\inf_{x \in X} \theta(x) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) =\inf_{x \in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\leq \theta(y) +\frac{1}{\gamma}D_f(y,y) =\theta(y). 
\end{equation}
Therefore,
\begin{equation}
\label{e:170428a}
\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
Taking now the infimum over $y\in U$ yields
$\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$.
Consequently, 
\begin{equation}
\inf \theta(X) \leq \varliminf_{\gamma \to+\infty}
\benv[\gamma]{\theta}(y).
\end{equation}
On the other hand, $(\forall x \in X)$ $\benv[\gamma]{\theta}(y) \leq \theta(x) +\frac{1}{\gamma}D_f(x,y)$, 
which implies that $(\forall x \in X)$ $\varlimsup_{\gamma
\to+\infty} \benv[\gamma]{\theta}(y) \leq \theta(x)$ and thus
$\varlimsup_{\gamma \to+\infty} \benv[\gamma]{\theta}(y) \leq
\inf \theta(X)$. 
Altogether,
$\lim_{\gamma\to+\infty} \benv[\gamma]{\theta}(y) =
\inf \theta(X)$ and the conclusion follows from
\eqref{e:170428a}. 

\ref{p:12.9_right}: This is similar to \ref{p:12.9_left}. 
\end{proof}

\begin{proof}
\ref{p:12.9_left}: We first show that $\dom\benv[\gamma]{\theta}=U$.
Let $y \in \dom\benv[\gamma]{\theta}$. 
Then $\benv[\gamma]{\theta}(y) =\inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big) <+\infty$,
and hence there exists $x \in X$ such that $\theta(x) +\frac{1}{\gamma}D_f(x,y) <+\infty$.
Since $\theta(x) >-\infty$, this yields $y \in U$.

From now on, let $y \in U$, and pick $u \in \dom\theta \cap U$. 
Then $-f(y) <+\infty$, $\|\nabla f(y)\| <+\infty$, $f(u) <+\infty$, $\theta(u) <+\infty$, and
\begin{subequations}
\begin{align}
\benv[\gamma]{\theta}(y) &=\inf_{x\in X} \Big(\theta(x) +\frac{1}{\gamma}\big(f(x) -f(y) -\scal{\nabla f(y)}{x -y}\big)\Big), \\ 
&\leq \theta(u) +\frac{1}{\gamma}\big(f(u) -f(y) -\scal{\nabla f(y)}{u -y}\big) <+\infty,
\end{align}
\end{subequations} 
which gives $y \in \dom\benv[\gamma]{\theta}$. Hence, $\dom \benv[\gamma]{\theta} =U$.

Next, let $\mu \in \left]\gamma, +\infty\right[$. 
Then $\frac{1}{\mu} < \frac{1}{\gamma}$, 
$\theta \leq \theta +\frac{1}{\mu}D_f(\cdot,y) \leq \theta +\frac{1}{\gamma}D_f(\cdot,y)$, and so
\begin{equation}
\inf_{x \in X} \theta(x) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) =\inf_{x \in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\leq \theta(y) +\frac{1}{\gamma}D_f(y,y) =\theta(y). 
\end{equation}
Therefore,
\begin{equation}
\label{e:170428a}
\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
Taking now the infimum over $y\in U$ yields
$\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$.

Consequently, 
\begin{equation}
\inf \theta(X) \leq \varliminf_{\gamma \to+\infty}
\benv[\gamma]{\theta}(y).
\end{equation}

\begin{corollary}
\label{c:BregProj}
Let $C$ be a closed convex subset of $X$ such that 
$U\cap C\neq\varnothing$, 
let $(x,y) \in U\times U$, 
and let $p \in U\cap C$.
Then the following hold:
\begin{enumerate}
\item 
\label{c:BregProj_left}
$p =\bproj{C}y \ \Leftrightarrow \ (\forall z \in C)\; 
\scal{\nabla f(y) -\nabla f(p)}{z -p} \leq 0$. 
\item 
\label{c:BregProj_right}
$p =\fproj{C}x \ \Leftrightarrow \ (\forall z \in C)\; 
\scal{\nabla^2 f(p)(x -p)}{z -p} \leq 0$. 
\end{enumerate}
\end{corollary}

\begin{proof}
In light of \cref{d:BregProj}, we 
apply \cref{p:prox} 
(see also \cite[Proposition~3.16]{BB97}).
\end{proof}

\begin{proposition}
\label{p:limthetaprox}
Let $\theta\in\Gamma_0(X)$ be such that $U\cap \dom\theta\neq\varnothing$ and let $x, y \in U$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:limthetaprox_left}
If \eqref{e:bcoeR} holds for all $\gamma\in\RPP$, 
then $\theta(\bprox{\gamma\theta}(y)) \to \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\item 
\label{p:limthetaprox_right}
If \eqref{e:fcoeR} holds for all $\gamma\in \RPP$, then  
$\theta(\fprox{\gamma\theta}(x)) \to \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\end{enumerate}	
\end{proposition}

\begin{proof}
We shall just prove \ref{p:limthetaprox_left} 
because the proof of \ref{p:limthetaprox_right} is similar.
Assume that \eqref{e:bcoeR} holds for all 
$\gamma \in \RPP$.
Combining \eqref{e:benv-bprox'} with \cref{p:12.9}\ref{p:12.9_left} yields
\begin{equation}
\inf\theta(X) \leq \theta\big(\bprox{\gamma\theta}(y)\big) \leq \benv[\gamma]{\theta}(y) \to \inf\theta(X) 
\quad\text{as}\quad \gamma \uparrow +\infty,
\end{equation} 
which implies that $\theta(\bprox{\gamma\theta}(y)) \to 
\inf\theta(X)$ as $\gamma \uparrow +\infty$. 
\end{proof}

\begin{proof}
We shall just prove \ref{p:limthetaprox_left} 
because the proof of \ref{p:limthetaprox_right} is similar.

\begin{theorem}
\label{p:limprox+}
Let $\theta\in\Gamma_0(X)$ be coercive such that 
$U\cap \dom\theta\neq\varnothing$ and let $x, y \in U$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:limprox+_left}
The net $(\bprox{\gamma\theta}(y))_{\gamma \in \RPP}$ is bounded 
with all cluster points as $\gamma \uparrow +\infty$ lying in $\argmin\theta$. 
Moreover,
	\begin{enumerate}
	\item\label{p:limprox+_leftA} 
	if $\argmin\theta$ is a singleton, 
	then $\bprox{\gamma\theta}(y) \to \argmin\theta$ as $\gamma \uparrow +\infty$;
	\item\label{p:limprox+_leftP} 
	if $\argmin\theta \subseteq U$, 
	then $\bprox{\gamma\theta}(y) \to \bproj{\argmin\theta}y$ as $\gamma \uparrow +\infty$. 
	\end{enumerate}

\item 
\label{p:limprox+_right}
The net $(\fprox{\gamma\theta}(x))_{\gamma \in \RPP}$ is bounded 
with all cluster points as $\gamma \uparrow +\infty$ lying in $\argmin\theta$. 
Moreover,
	\begin{enumerate}
	\item 
	if $\argmin\theta$ is a singleton, 
	then $\fprox{\gamma\theta}(x) \to \argmin\theta$ as $\gamma \uparrow +\infty$;
	\item\label{p:limprox+_rightP} 
	if $\argmin\theta \subseteq U$, 
	then $\fprox{\gamma\theta}(x) \to \fproj{\argmin\theta}x$ as $\gamma \uparrow +\infty$.  
	\end{enumerate}
\end{enumerate}	
\end{theorem}

\item\label{p:limprox+_leftP} 
if $\argmin\theta \subseteq U$, 
then $\bprox{\gamma\theta}(y) \to \bproj{\argmin\theta}y$ as $\gamma \uparrow +\infty$.

\item\label{p:limprox+_rightP} 
if $\argmin\theta \subseteq U$, 
then $\fprox{\gamma\theta}(x) \to \fproj{\argmin\theta}x$ as $\gamma \uparrow +\infty$.

\ref{p:limprox+_left}: It follows from \eqref{e:benv-bprox'} that   
\begin{equation}
\label{e:bounded}
(\forall \gamma \in \RPP)\quad \bprox{\gamma\theta}(y) \in \lev{\theta(y)}\theta,
\end{equation}
and then
from the coercivity of $\theta$ and \cite[Proposition~11.12]{BC17} that $(\bprox{\gamma\theta}(y))_{\gamma \in \RPP}$ is bounded.

and by Proposition~\ref{p:prox}\ref{p:prox_left},
\begin{equation}
\scal{\nabla f(y) -\nabla f\big(\bprox{\gamma_n\theta}(y)\big)}{z -\bprox{\gamma_n\theta}(y)} 
\leq \gamma_n\Big(\theta(z)
-\theta\big(\bprox{\gamma_n\theta}(y)\big)\Big) \leq 0.
\end{equation}

Taking the limit as $n \to +\infty$ and using the continuity of $\nabla f$ yield
\begin{equation}
\scal{\nabla f(y) -\nabla f(y')}{z -y'} \leq 0.
\end{equation}

\ref{p:limprox+_right}: 
The proof is similar to the one of \ref{p:limprox+_left}.
\end{proof}

We assume throughout that
\begin{empheq}[box=\mybluebox]{equation}
\text{$X := \RR^J$,}
\end{empheq}
which we equip with 
the standard inner product $\scal{\cdot}{\cdot}$ and 
the induced Euclidean norm $\|\cdot\|$.

Now assume that 
\begin{empheq}[box=\mybluebox]{equation}
\text{$f \colon X \to\left]-\infty, +\infty\right]$ is convex and
differentiable on $U := \intdom f \neq\varnothing$.}
\end{empheq}

The \emph{Bregman distance}\footnote{Note that $D_f$ is
\emph{not} a distance in the sense of metric topology; however,
this naming convention is now ubiquitous.}  associated with $f$, 
first explored by Bregman in \cite{Bre67} (see also
\cite{CZ97}), is 
\begin{equation} 
\label{e:Df}
D_f \colon X \times X \to \left[0, +\infty\right] \colon (x,y) \mapsto
\begin{cases}
f(x) -f(y) -\scal{\nabla f(y)}{x -y}, &\text{~if~} y\in U; \\
+\infty, &\text{~otherwise}.
\end{cases}
\end{equation}

\begin{equation}
\label{e:bba}
\benv[\gamma]{\theta} \colon X\to \left[-\infty, +\infty\right] \colon
y\mapsto \inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\end{equation}
and

\begin{equation}
\label{e:fba}
\fenv[\gamma]{\theta} \colon X \to \left[-\infty, +\infty\right] \colon
x \mapsto
\inf_{y\in X} \big(\theta(y) +\frac{1}{\gamma}D_f(x,y)\big),
\end{equation}
respectively.

\begin{proposition}
\label{p:12.22i}
Let $\theta \colon X \to \left]-\infty, +\infty\right]$, 
let $\gamma \in \RPP$, and let $\mu \in \RPP$.
Then $\benv[\mu]{\gamma\theta} =\gamma\benv[\gamma\mu]{\theta}$ 
and $\fenv[\mu]{\gamma\theta} =\gamma\fenv[\gamma\mu]{\theta}$.
\end{proposition}

\begin{proof}
This is analogous to the proof of \cite[Proposition~12.22(i)]{BC17}.
\end{proof}

From now on, we strengthen our assumptions by requiring that 
\begin{empheq}[box=\mybluebox]{equation}
\label{e:fLegendre}
\text{$f\in\Gamma_0(X)$ is a convex function of Legendre type and
$U := \intdom f$.}
\end{empheq}
This will allow us to obtain a quite satisfying theory in which
the envelopes are convex functions. 
Note that $f$ is essentially smooth and essentially strictly convex in the sense of \cite[Section~26]{Roc70}.

It is well known that
\begin{equation}
\label{e:Leggy}
\nabla f\colon U\to U^*:= \intdom f^*
\text{~is a homeomorphism with~}
\big(\nabla f\big)^{-1} = \nabla f^*.
\end{equation}

We will also work with the following standard assumptions:
\begin{itemize}
\item[\bfseries A1] 
$\nabla^2 f$ exists and is continuous on $U$;

\item[\bfseries A4] 
$(\forall x\in U)$ $D_f(x,\cdot)$ is coercive, i.e., 
$D_f(x, y) \to +\infty$ as $\|y\| \to +\infty$.
\end{itemize}
We also henceforth assume that 
\begin{empheq}[box=\mybluebox]{equation}
\text{all assumptions \textbf{A1}--\textbf{A4} hold.}
\end{empheq}

\begin{fact} 
\label{f:coeR}
Let $\theta\in\Gamma_0(X)$ be such that $\dom\theta\cap U\neq\varnothing$ and let $\gamma \in \RPP$.
Consider the following properties:
\begin{itemize}
\item[\rm (a)]
$U\cap \dom\theta$ is bounded.
\item[\rm (b)]
$\inf\theta(U)>-\infty$.
\item[\rm (c)]
$f$ is supercoercive, i.e., 
$f(x)/\|x\| \to +\infty$ as $\|x\| \to +\infty$.
\item[\rm (d)]
$(\forall x\in U)$ $D_f(x,\cdot)$ is supercoercive.
\end{itemize}
Then the following hold:
\begin{enumerate}
\item \label{l:coeRi}
If any of the conditions (a), (b), or (c) holds, then 
\begin{equation} \label{e:bcoeR}
(\forall y \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(\cdot,y) \;\;
\text{is coercive}
\end{equation}
or, equivalently,
\begin{equation}
\frac{1}{\gamma}\ran\nabla f \subseteq \intdom\left(\frac{1}{\gamma}f +\theta\right)^*.
\label{e:brilliantissimo}
\end{equation}

\item \label{l:coeRii}
If any of the conditions (a), (b), or (d) holds, then 
\begin{equation} \label{e:fcoeR}
(\forall x \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(x,\cdot) \;\;
\text{is coercive.}
\end{equation}
\end{enumerate}
\end{fact}

\begin{proof}
Since $\frac{1}{\gamma}D_f =D_{\frac{1}{\gamma}f}$,
the result follows from \cite[Lemma~2.12]{BCN06} 
applied to $\tfrac{1}{\gamma}f$.
\end{proof}

\begin{equation} \label{e:bcoeR}
(\forall y \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(\cdot,y) \;\;
\text{is coercive}
\end{equation}

\begin{equation} \label{e:fcoeR}
(\forall x \in U) \quad \theta(\cdot) + \frac{1}{\gamma}D_f(x,\cdot) \;\;
\text{is coercive.}
\end{equation}

\begin{proposition} 
\label{p:exact} 
Let $\theta \colon X \to \left]-\infty, +\infty\right]$ be convex
and such that $U\cap \dom\theta\neq\varnothing$, and let $\gamma \in \RPP$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:exact_left}
$\benv[\gamma]{\theta}$ is convex and continuous on $U$, and
	\begin{enumerate}
	\item 
	if \eqref{e:bcoeR} holds, i.e., $(\forall y \in U)$ $\theta(\cdot) +\frac{1}{\gamma}D_f(\cdot,y)$ is coercive, 
	then $\benv[\gamma]{\theta}$ is proper; 
	\item
	if $\theta\in\Gamma_0(X)$ and $\theta(\cdot) +\frac{1}{\gamma}D_f(\cdot,y)$ is coercive for a given $y\in U$, 
	then there exists a unique point $z\in U$ such that $\benv[\gamma]{\theta}(y)=\theta(z) +\frac{1}{\gamma}D_f(z,y)$.
	\end{enumerate}

\item 
\label{p:exact_right} 
$\fenv[\gamma]{\theta}$ is convex and continuous on $U$, and
	\begin{enumerate}
	\item 
	if \eqref{e:fcoeR} holds, i.e., $(\forall x \in U)$ $\theta(\cdot) +\frac{1}{\gamma}D_f(x,\cdot)$ is coercive, 
	then $\fenv[\gamma]{\theta}$ is proper; 
	\item
	if $\theta\in\Gamma_0(X)$ and $\theta(\cdot) +\frac{1}{\gamma}D_f(x,\cdot)$ is coercive for a given $x\in U$, 
	then there exists a unique point $z\in U$ such that $\fenv[\gamma]{\theta}(z)=\theta(z) +\frac{1}{\gamma}D_f(x,z)$.
	\end{enumerate}
\end{enumerate}
\end{proposition}

\begin{proof}
Since $\frac{1}{\gamma}D_f =D_{\frac{1}{\gamma}f}$,
the result follows from
 \cite[Propositions~3.4 and 3.5]{BCN06}
applied to $\tfrac{1}{\gamma}f$.
\end{proof}

If \eqref{e:fcoeR} holds for $\gamma =1$, then 
the \emph{right proximity operator} associated with $\theta$ is
\begin{equation} \label{e:dfprox}
\fprox{\theta}\colon U \to  U \colon
x \mapsto
\underset{y\in X}{\operatorname{argmin}}\;\: \big(\theta(y) +D_f(x,y)\big).
\end{equation}
\end{definition}

We thus derive from the definition that if \eqref{e:bcoeR} holds, then
\begin{subequations}
\label{e:benv-bproxall}
\begin{equation}
\label{e:benv-bprox}
\benv[\gamma]{\theta}(y) =\theta\big(\bprox{\gamma\theta}(y)\big) 
+\frac{1}{\gamma}D_f\big(\bprox{\gamma\theta}(y), y\big)
\end{equation}

and, by combining with \cref{p:12.9}\ref{p:12.9_left},
\begin{equation}
\label{e:benv-bprox'}
\theta\big(\bprox{\gamma\theta}(y)\big) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
\end{subequations}

Similarly, if \eqref{e:fcoeR} holds, then
\begin{subequations}
\label{e:fenv-fproxall}
\begin{equation}
\label{e:fenv-fprox}
\fenv[\gamma]{\theta}(x) =\theta\big(\fprox{\gamma\theta}(x)\big) +
\frac{1}{\gamma}D_f\big(x, \fprox{\gamma\theta}(x)\big)
\end{equation}

and 
\begin{equation}
\theta\big(\fprox{\gamma\theta}(x)\big) \leq \fenv[\gamma]{\theta}(x) \leq \theta(x).
\end{equation}
\end{subequations}
\end{remark}

\begin{proposition}
\label{p:prox}
Let $\theta\in\Gamma_0(X)$ be such that $\dom\theta\cap U\neq\varnothing$ and let $\gamma \in \RPP$.
\begin{enumerate}
\item 
\label{p:prox_left}
Suppose that \eqref{e:bcoeR} holds.
Then for every $(x,y) \in U\times U$, 
the following conditions are equivalent:
	\begin{enumerate}
	\item 
	$x =\bprox{\gamma\theta}(y)$,
	\item 
	$0 \in \gamma\partial\theta(x) +\nabla f(x) -\nabla f(y)$,
	\item 
	$(\forall z \in X)\quad \scal{\nabla f(y) -\nabla f(x)}{z -x} +\gamma\theta(x) \leq \gamma\theta(z)$.
	\end{enumerate}
Moreover, 
\begin{equation} \label{e:pro}
\bprox{\gamma\theta}=(\nabla f +\gamma\partial\theta)^{-1}\circ \nabla f 
\end{equation}
is continuous on $U$. 
\item 
\label{p:prox_right}
Suppose that \eqref{e:fcoeR} holds. 
Then for every $(x,y) \in U\times U$, 
the following conditions are equivalent:
	\begin{enumerate}
	\item 
	$y =\fprox{\gamma\theta}(x)$,
	\item 
	$0 \in \gamma\partial\theta(y) +\nabla^2 f(y)(y -x)$,
	\item 
	$(\forall z \in X)\quad \scal{\nabla^2 f(y)(x -y)}{z -y} +\gamma\theta(y) \leq \gamma\theta(z)$.
	\end{enumerate}
Moreover, $\fprox{\gamma\theta}$ is continuous on $U$. 
\end{enumerate}
\end{proposition}

\begin{proof}
Apply \cite[Proposition~3.10]{BCN06} to $\gamma\theta$.
\end{proof}

\begin{lemma}
\label{l:cvg}
Let $C$ be a compact subset of a Hausdorff space $\mathcal X$,
let $\phi\colon \mathcal X \to \left[-\infty, +\infty\right]$ be lower 
semicontinuous,
let $(x_a)_{a\in A}$ be a net in $C$,
and suppose that $\phi(x_a) \to \inf\phi(\mathcal X)$. 
Then $\argmin\phi \neq\varnothing$ 
and all cluster points of $(x_a)_{a\in A}$ lie in $\argmin\phi$.
Consequently, if $\phi$ attains its minimum at a unique point $u$, then $x_a \to u$.
\end{lemma}

\begin{proof}
This follows from the lower semicontinuity of $\phi$ and \cite[Lemma 1.14]{BC17}.
\end{proof}

\begin{proposition} 
\label{p:12.9} 
Let $\theta \colon X \to \left]-\infty, +\infty\right]$ be such that $U\cap \dom\theta\neq\varnothing$ and let $\gamma \in \RPP$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:12.9_left}
$\dom\benv[\gamma]{\theta}=U$, 
and $(\forall y\in U)(\forall\mu \in \left]\gamma, +\infty\right[)$ 
$\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y)$.
Consequently, $\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$, 
and $\benv[\gamma]{\theta}(y) \downarrow \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\item 
\label{p:12.9_right}
$\dom\fenv[\gamma]{\theta}=\dom f$, 
and $(\forall x \in U)(\forall\mu \in \left]\gamma, +\infty\right[)$ 
$\inf \theta(X) \leq \fenv[\mu]{\theta}(x) \leq \fenv[\gamma]{\theta}(x) \leq \theta(x)$.
Consequently, $\inf \theta(X) \leq \inf \fenv[\gamma]{\theta}(X) \leq \inf \theta(U)$, 
and $\fenv[\gamma]{\theta}(x) \downarrow \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\end{enumerate}
\end{proposition}

\begin{proof}
\ref{p:12.9_left}: We first show that $\dom\benv[\gamma]{\theta}=U$.
Let $y \in \dom\benv[\gamma]{\theta}$. 
Then $\benv[\gamma]{\theta}(y) =\inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big) <+\infty$,
and hence there exists $x \in X$ such that $\theta(x) +\frac{1}{\gamma}D_f(x,y) <+\infty$.
Since $\theta(x) >-\infty$, this yields $y \in U$.

From now on, let $y \in U$, and pick $u \in \dom\theta \cap U$. 
Then $-f(y) <+\infty$, $\|\nabla f(y)\| <+\infty$, $f(u) <+\infty$, $\theta(u) <+\infty$, and
\begin{subequations}
\begin{align}
\benv[\gamma]{\theta}(y) &=\inf_{x\in X} \Big(\theta(x) +\frac{1}{\gamma}\big(f(x) -f(y) -\scal{\nabla f(y)}{x -y}\big)\Big), \\ 
&\leq \theta(u) +\frac{1}{\gamma}\big(f(u) -f(y) -\scal{\nabla f(y)}{u -y}\big) <+\infty,
\end{align}
\end{subequations} 
which gives $y \in \dom\benv[\gamma]{\theta}$. Hence, $\dom \benv[\gamma]{\theta} =U$. 

Next, let $\mu \in \left]\gamma, +\infty\right[$. 
Then $\frac{1}{\mu} < \frac{1}{\gamma}$, 
$\theta \leq \theta +\frac{1}{\mu}D_f(\cdot,y) \leq \theta +\frac{1}{\gamma}D_f(\cdot,y)$, and so
\begin{equation}
\inf_{x \in X} \theta(x) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) =\inf_{x \in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\leq \theta(y) +\frac{1}{\gamma}D_f(y,y) =\theta(y). 
\end{equation}
Therefore,
\begin{equation}
\label{e:170428a}
\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
Taking now the infimum over $y\in U$ yields
$\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$.
Consequently, 
\begin{equation}
\inf \theta(X) \leq \varliminf_{\gamma \to+\infty}
\benv[\gamma]{\theta}(y).
\end{equation}
On the other hand, $(\forall x \in X)$ $\benv[\gamma]{\theta}(y) \leq \theta(x) +\frac{1}{\gamma}D_f(x,y)$, 
which implies that $(\forall x \in X)$ $\varlimsup_{\gamma
\to+\infty} \benv[\gamma]{\theta}(y) \leq \theta(x)$ and thus
$\varlimsup_{\gamma \to+\infty} \benv[\gamma]{\theta}(y) \leq
\inf \theta(X)$. 
Altogether,
$\lim_{\gamma\to+\infty} \benv[\gamma]{\theta}(y) =
\inf \theta(X)$ and the conclusion follows from
\eqref{e:170428a}. 

\ref{p:12.9_right}: This is similar to \ref{p:12.9_left}. 
\end{proof}

\begin{proof}
\ref{p:12.9_left}: We first show that $\dom\benv[\gamma]{\theta}=U$.
Let $y \in \dom\benv[\gamma]{\theta}$. 
Then $\benv[\gamma]{\theta}(y) =\inf_{x\in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big) <+\infty$,
and hence there exists $x \in X$ such that $\theta(x) +\frac{1}{\gamma}D_f(x,y) <+\infty$.
Since $\theta(x) >-\infty$, this yields $y \in U$.

From now on, let $y \in U$, and pick $u \in \dom\theta \cap U$. 
Then $-f(y) <+\infty$, $\|\nabla f(y)\| <+\infty$, $f(u) <+\infty$, $\theta(u) <+\infty$, and
\begin{subequations}
\begin{align}
\benv[\gamma]{\theta}(y) &=\inf_{x\in X} \Big(\theta(x) +\frac{1}{\gamma}\big(f(x) -f(y) -\scal{\nabla f(y)}{x -y}\big)\Big), \\ 
&\leq \theta(u) +\frac{1}{\gamma}\big(f(u) -f(y) -\scal{\nabla f(y)}{u -y}\big) <+\infty,
\end{align}
\end{subequations} 
which gives $y \in \dom\benv[\gamma]{\theta}$. Hence, $\dom \benv[\gamma]{\theta} =U$.

Next, let $\mu \in \left]\gamma, +\infty\right[$. 
Then $\frac{1}{\mu} < \frac{1}{\gamma}$, 
$\theta \leq \theta +\frac{1}{\mu}D_f(\cdot,y) \leq \theta +\frac{1}{\gamma}D_f(\cdot,y)$, and so
\begin{equation}
\inf_{x \in X} \theta(x) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) =\inf_{x \in X} \big(\theta(x) +\frac{1}{\gamma}D_f(x,y)\big)
\leq \theta(y) +\frac{1}{\gamma}D_f(y,y) =\theta(y). 
\end{equation}
Therefore,
\begin{equation}
\label{e:170428a}
\inf \theta(X) \leq \benv[\mu]{\theta}(y) \leq \benv[\gamma]{\theta}(y) \leq \theta(y).
\end{equation}
Taking now the infimum over $y\in U$ yields
$\inf \theta(X) \leq \inf \benv[\gamma]{\theta}(X) \leq \inf \theta(U)$.

Consequently, 
\begin{equation}
\inf \theta(X) \leq \varliminf_{\gamma \to+\infty}
\benv[\gamma]{\theta}(y).
\end{equation}

\begin{corollary}
\label{c:BregProj}
Let $C$ be a closed convex subset of $X$ such that 
$U\cap C\neq\varnothing$, 
let $(x,y) \in U\times U$, 
and let $p \in U\cap C$.
Then the following hold:
\begin{enumerate}
\item 
\label{c:BregProj_left}
$p =\bproj{C}y \ \Leftrightarrow \ (\forall z \in C)\; 
\scal{\nabla f(y) -\nabla f(p)}{z -p} \leq 0$. 
\item 
\label{c:BregProj_right}
$p =\fproj{C}x \ \Leftrightarrow \ (\forall z \in C)\; 
\scal{\nabla^2 f(p)(x -p)}{z -p} \leq 0$. 
\end{enumerate}
\end{corollary}

\begin{proof}
In light of \cref{d:BregProj}, we 
apply \cref{p:prox} 
(see also \cite[Proposition~3.16]{BB97}).
\end{proof}

\begin{proposition}
\label{p:limthetaprox}
Let $\theta\in\Gamma_0(X)$ be such that $U\cap \dom\theta\neq\varnothing$ and let $x, y \in U$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:limthetaprox_left}
If \eqref{e:bcoeR} holds for all $\gamma\in\RPP$, 
then $\theta(\bprox{\gamma\theta}(y)) \to \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\item 
\label{p:limthetaprox_right}
If \eqref{e:fcoeR} holds for all $\gamma\in \RPP$, then  
$\theta(\fprox{\gamma\theta}(x)) \to \inf \theta(X)$ as $\gamma \uparrow +\infty$.
\end{enumerate}	
\end{proposition}

\begin{proof}
We shall just prove \ref{p:limthetaprox_left} 
because the proof of \ref{p:limthetaprox_right} is similar.

\begin{proof}
We shall just prove \ref{p:limthetaprox_left} 
because the proof of \ref{p:limthetaprox_right} is similar.
Assume that \eqref{e:bcoeR} holds for all 
$\gamma \in \RPP$.
Combining \eqref{e:benv-bprox'} with \cref{p:12.9}\ref{p:12.9_left} yields
\begin{equation}
\inf\theta(X) \leq \theta\big(\bprox{\gamma\theta}(y)\big) \leq \benv[\gamma]{\theta}(y) \to \inf\theta(X) 
\quad\text{as}\quad \gamma \uparrow +\infty,
\end{equation} 
which implies that $\theta(\bprox{\gamma\theta}(y)) \to 
\inf\theta(X)$ as $\gamma \uparrow +\infty$. 
\end{proof}

\begin{theorem}
\label{p:limprox+}
Let $\theta\in\Gamma_0(X)$ be coercive such that 
$U\cap \dom\theta\neq\varnothing$ and let $x, y \in U$.
Then the following hold:
\begin{enumerate}
\item 
\label{p:limprox+_left}
The net $(\bprox{\gamma\theta}(y))_{\gamma \in \RPP}$ is bounded 
with all cluster points as $\gamma \uparrow +\infty$ lying in $\argmin\theta$. 
Moreover,
	\begin{enumerate}
	\item\label{p:limprox+_leftA} 
	if $\argmin\theta$ is a singleton, 
	then $\bprox{\gamma\theta}(y) \to \argmin\theta$ as $\gamma \uparrow +\infty$;
	\item\label{p:limprox+_leftP} 
	if $\argmin\theta \subseteq U$, 
	then $\bprox{\gamma\theta}(y) \to \bproj{\argmin\theta}y$ as $\gamma \uparrow +\infty$. 
	\end{enumerate}

\item 
\label{p:limprox+_right}
The net $(\fprox{\gamma\theta}(x))_{\gamma \in \RPP}$ is bounded 
with all cluster points as $\gamma \uparrow +\infty$ lying in $\argmin\theta$. 
Moreover,
	\begin{enumerate}
	\item 
	if $\argmin\theta$ is a singleton, 
	then $\fprox{\gamma\theta}(x) \to \argmin\theta$ as $\gamma \uparrow +\infty$;
	\item\label{p:limprox+_rightP} 
	if $\argmin\theta \subseteq U$, 
	then $\fprox{\gamma\theta}(x) \to \fproj{\argmin\theta}x$ as $\gamma \uparrow +\infty$.  
	\end{enumerate}
\end{enumerate}	
\end{theorem}

\item\label{p:limprox+_leftP} 
if $\argmin\theta \subseteq U$, 
then $\bprox{\gamma\theta}(y) \to \bproj{\argmin\theta}y$ as $\gamma \uparrow +\infty$.

\item\label{p:limprox+_rightP} 
if $\argmin\theta \subseteq U$, 
then $\fprox{\gamma\theta}(x) \to \fproj{\argmin\theta}x$ as $\gamma \uparrow +\infty$.

\ref{p:limprox+_left}: It follows from \eqref{e:benv-bprox'} that   
\begin{equation}
\label{e:bounded}
(\forall \gamma \in \RPP)\quad \bprox{\gamma\theta}(y) \in \lev{\theta(y)}\theta,
\end{equation}
and then
from the coercivity of $\theta$ and \cite[Proposition~11.12]{BC17} that $(\bprox{\gamma\theta}(y))_{\gamma \in \RPP}$ is bounded.

